contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address observer) public payable {
        require(observer != address(0), "observer must be nonzero");

        uint256 beforeObs = c.getBalance(observer); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterObs = c.getBalance(observer); if (__ESBMC_reverted()) return;

        assert(reverted || (afterObs == beforeObs && c.getBalance(msg.sender) == 0));
    }

    receive() external payable {}
}

