pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(address observer) internal {
        vm.assume(observer != address(0));
        uint256 beforeObs;
        try c.getBalance(observer) returns (uint256 __r) { beforeObs = __r; } catch { return; }
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterObs;
        try c.getBalance(observer) returns (uint256 __r) { afterObs = __r; } catch { return; }
        assertTrue(reverted || (afterObs == beforeObs && c.getBalance(msg.sender) == 0));
    }

    function testFuzz_run(address observer) public {
        vm.assume(observer.code.length == 0 && uint160(observer) > 0xffff && observer != address(this) && observer != address(c) && observer != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && observer != 0x000000000000000000636F6e736F6c652e6c6f67 && observer != 0x4e59b44847b379578588920cA78FbF26c0B4956C && observer != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(observer);
    }

    receive() external payable {}
}
